def json_pointer(doc, pointer: str):
    if pointer == '':
        return doc
    if not pointer.startswith('/'):
        raise ValueError("Pointer must start with '/'")

    segments = pointer.split('/')[1:]
    current = doc
    for seg in segments:
        seg = seg.replace('~1', '/').replace('~0', '~')
        if isinstance(current, dict):
            if seg not in current:
                raise ValueError(f"Key not found: {seg}")
            current = current[seg]
        elif isinstance(current, list):
            if not seg.isdigit():
                raise ValueError(f"Invalid list index: {seg}")
            idx = int(seg)
            if idx < 0 or idx >= len(current):
                raise ValueError(f"Index out of range: {idx}")
            current = current[idx]
        else:
            raise ValueError("Cannot index into non-dict/list")
    return current
